const pnlEUR    = valeurEUR - (totalUSDT / 1.08);
const pnlPct    = ((valeurEUR - totalUSDT/1.08) / (totalUSDT/1.08)) * 100;

// Valeur actuelle en USD (pour Telegram)
const currentValueUSD = totalBTC * execPrice;
const pnlUSD = currentValueUSD - totalUSDT;

delete staticData.pendingDCA;

return [{
  json: {
    // Champs PostgreSQL
    montant_eur:   parseFloat((montantUSDT / 1.08).toFixed(2)),
    montant_usdt:  montantUSDT,
    btc_price:     execPrice,
    btc_quantity:  execQty,
    total_btc:     parseFloat(totalBTC.toFixed(8)),
    avg_price:     parseFloat(avgPrice.toFixed(2)),
    valeur_eur:    parseFloat(valeurEUR.toFixed(2)),
    pnl_eur:       parseFloat(pnlEUR.toFixed(2)),
    pnl_pct:       parseFloat(pnlPct.toFixed(4)),
    simulation:    staticData.simulation_dca !== false,

    // Champs Notify DCA
    btcPrice:      execPrice.toFixed(2),
    quantityBTC:   execQty.toFixed(8),
    montantUSDT:   montantUSDT.toFixed(2),
    totalBTC:      totalBTC.toFixed(8),
    totalSpent:    totalUSDT.toFixed(2),
    avgBuyPrice:   avgPrice.toFixed(2),
    currentValue:  currentValueUSD.toFixed(2),
    pnlUSD:        pnlUSD.toFixed(2),
    pnlPct:        pnlPct.toFixed(2),
    orderId:       order.orderId
  }
}];

