const ema = (data, period) => { const k = 2 / (period + 1); let v = data[0]; for (let i = 1; i < data.length; i++) v = data[i] * k + v * (1 - k); return v; };
const ema9_1h = ema(closes, 9);
const ema26_1h = ema(closes, 26);
return [{ json: { ema9_1h: parseFloat(ema9_1h.toFixed(2)), ema26_1h: parseFloat(ema26_1h.toFixed(2)), trendUp: ema9_1h > ema26_1h, trendDown: ema9_1h < ema26_1h } }];

const candles = $input.all();
return candles.map(candle => {
  const kline = candle.json;
  return { json: { openTime: parseFloat(kline[0]), open: parseFloat(kline[1]), high: parseFloat(kline[2]), low: parseFloat(kline[3]), close: parseFloat(kline[4]), volume: parseFloat(kline[7]) } };
});

const items = $input.all();
if (!items || items.length === 0) return [{ json: { error: 'No 5M data', prix_actuel: 0, rsi_14: 50, atr: 0, atrPercent: 0, ema9: 0 } }];
const closes = items.map(i => parseFloat(i.json.close));
const highs = items.map(i => parseFloat(i.json.high));
const lows = items.map(i => parseFloat(i.json.low));
const currentPrice = closes[closes.length - 1];
const emaCalc = (data, period) => { if (data.length < period) return data[data.length-1]; const k = 2/(period+1); let v = data[0]; for (let i=1;i<data.length;i++) v=data[i]*k+v*(1-k); return v; };
const rsiCalc = (closes, period=14) => { if (closes.length < period+1) return 50; let gains=0,losses=0; for (let i=1;i<=period;i++) { const c=closes[closes.length-i]-closes[closes.length-i-1]; if(c>0) gains+=c; else losses+=Math.abs(c); } const ag=gains/period,al=losses/period; if(al===0) return ag>0?100:50; return 100-(100/(1+ag/al)); };
const atrCalc = (h,l,c,period=14) => { if (c.length<period+1) return 0; let trs=[]; for(let i=1;i<c.length;i++) trs.push(Math.max(h[i]-l[i],Math.abs(h[i]-c[i-1]),Math.abs(l[i]-c[i-1]))); return trs.slice(-period).reduce((a,b)=>a+b,0)/period; };
const ema9=emaCalc(closes,9); const rsi14=rsiCalc(closes,14); const atr=atrCalc(highs,lows,closes,14);
const atrPercent=currentPrice>0?(atr/currentPrice)*100:0;
return [{ json: { prix_actuel: parseFloat(currentPrice.toFixed(2)), ema9: parseFloat(ema9.toFixed(2)), rsi_14: parseFloat(rsi14.toFixed(2)), atr: parseFloat(atr.toFixed(2)), atrPercent: parseFloat(atrPercent.toFixed(4)), dataPoints: items.length } }];

// === RÉCUPÉRATION DES INDICATEURS ===
const inputs = $input.all();
