const prixActuel = ind5m.prix_actuel;
const ema9_5m = ind5m.ema9;
const rsi = ind5m.rsi_14;
const atrPct = ind5m.atrPercent;
const trendUp = ind1h.trendUp;
const trendDown = ind1h.trendDown;

// === CONDITIONS LONG ===
const validLong =
  prixActuel > ema9_5m &&
  trendUp &&        // EMA9 > EMA26 sur 1H
  trend4hUp &&      // EMA9 > EMA26 sur 4H (filtre tendance majeure)
  rsi < RSI_OVERSOLD &&
  atrPct >= MIN_ATR_PCT;

// === CONDITIONS SHORT ===
// Désactivé en réel — R/R insuffisant (1.053 sur 27 trades)
// Shadow mode actif avec filtres renforcés pour accumulation données
const validShort = false;

// === SHADOW SELL — filtres renforcés pour test ===
const shadowSell =
  prixActuel < ema9_5m &&        // prix sous EMA9 5m
  trendDown &&                    // trend 1H baissière
  rsi > RSI_SHORT_SHADOW &&       // RSI > 60 (surachat en tendance baissière)
  atrPct >= MIN_ATR_SHORT;        // ATR > 0.15% (volatilité suffisante)

// === ANALYSE DES RAISONS DE BLOCAGE ===
let blockedReason = '';
if (!validLong && !validShort) {
  const reasons = [];
  if (!trendUp && !trendDown) {
    reasons.push('trend_neutre');
  } else if (trendDown) {
    if (shadowSell) {
      reasons.push('SELL_shadow(RR<1.5)');
    } else {
      reasons.push('SELL_desactive(RR<1.5)');
    }
  } else if (trendUp && !validLong) {
