  bePct = applyFloor(row.be_long, FLOORS.BUY.be);
} else {
  tpPct = applyFloor(row.tp_sell, FLOORS.SELL.tp);
  slPct = applyFloor(row.sl_sell, FLOORS.SELL.sl);
  bePct = applyFloor(row.be_sell, FLOORS.SELL.be);
}

console.log(`Percentiles [${direction}] TP:${tpPct.toFixed(4)}% SL:${slPct.toFixed(4)}% BE:${bePct.toFixed(4)}%`);

