      signal_detected: false,
      direction: null,
      blocked_reason: `heure_bloquee(H${heureUTC})`
    }
  }];
}

// === SEUILS ===
const RSI_OVERSOLD = 40;
const RSI_SHORT = 45;
const MIN_ATR_PCT = 0.10;

// === VARIABLES ===
const prixActuel = ind5m.prix_actuel;
const ema9_5m = ind5m.ema9;
const rsi = ind5m.rsi_14;
const atrPct = ind5m.atrPercent;
const trendUp = ind1h.trendUp;
const trendDown = ind1h.trendDown;

// === CONDITIONS LONG ===
const validLong =
  prixActuel > ema9_5m &&
  trendUp &&
  rsi < RSI_OVERSOLD &&
  atrPct >= MIN_ATR_PCT;

// === CONDITIONS SHORT ===
// Désactivé — R/R structurel insuffisant (1.007 sur 15 trades)
// Réactiver quand R/R SELL > 1.5 sur 30+ trades SELL
const validShort = false;

// === ANALYSE DES RAISONS DE BLOCAGE ===
let blockedReason = '';
if (!validLong && !validShort) {
  const reasons = [];
  if (!trendUp && !trendDown) {
    reasons.push('trend_neutre');
  } else if (trendDown) {
    reasons.push('SELL_desactive(RR<1.5)');
  } else if (trendUp && !validLong) {
    if (rsi >= RSI_OVERSOLD) reasons.push(`rsi_trop_haut_long(${rsi.toFixed(1)})`);
    if (atrPct < MIN_ATR_PCT) reasons.push(`atr_faible(${atrPct.toFixed(4)}<${MIN_ATR_PCT})`);
    if (prixActuel <= ema9_5m) reasons.push('prix_sous_ema9');
  }
  blockedReason = reasons.join('|');
}

