parameters.jsCode:
// ─── Normalisation du payload ───────────────────────────────────────────
// Accepte DEUX formats :
//   1) Ancien modal produit unique : { produit, prix, quantite, client_nom, client_tel, ... }
//   2) Nouveau panier (une ligne par produit) : mêmes champs + prix_unitaire, total_panier, source
//
// Dans les deux cas on produit un objet normalisé identique pour les nœuds suivants.

const d = $input.first().json;

// Détection source
const source = d.source || 'site_modal';

// Produit / ligne
const produit      = d.produit      || '(inconnu)';
const prixLigne    = parseFloat((d.prix          || '0').toString().replace(',', '.'));
const quantite     = parseInt((d.quantite    || '1').toString());
const prixUnitaire = parseFloat((d.prix_unitaire || d.prix || '0').toString().replace(',', '.'));
const totalPanier  = parseFloat((d.total_panier  || d.prix || '0').toString().replace(',', '.'));
const categorie    = d.categorie    || '';
const nbArticles   = d.nb_articles  || '1';

// Client
const clientNom    = d.client_nom   || d.nom || '';
const clientTel    = d.client_tel   || d.tel || '';
const pays         = d.pays         || '';
const adresse      = d.adresse      || '';

// Date lisible
const now = new Date();
const dateStr = now.toLocaleDateString('fr-FR', {
  day: '2-digit', month: '2-digit', year: 'numeric',
  hour: '2-digit', minute: '2-digit'
});

// Label source pour la feuille
const sourceLabel = source === 'site_panier' ? 'Site (panier)'
  : source === 'site_modal' ? 'Site (direct)'
  : 'WhatsApp';

return [{
  json: {
    date:          dateStr,
    client_nom:    clientNom,
    client_tel:    clientTel,
    produit:       produit,
    quantite:      quantite,
    prix_ligne:    prixLigne.toFixed(2),
    prix_unitaire: prixUnitaire.toFixed(2),
    total_panier:  totalPanier.toFixed(2),
    nb_articles:   nbArticles,
    categorie:     categorie,
    pays:          pays,
    adresse:       adresse,
    source:        sourceLabel,
    statut:        'Nouveau',
    // Champs bruts conservés pour la notification WhatsApp
    _raw_produit:  produit,
    _raw_prix:     prixLigne,
    _raw_qty:      quantite,
    _client_nom:   clientNom,
    _client_tel:   clientTel,
    _total:        totalPanier
  }
}];

